{
  "findings": [
    {
      "check_id": "CKV_AWS_8",
      "title": "EC2 root volume encryption is not enforced",
      "resource": "aws_instance.web",
      "severity": "HIGH",
      "explanation": "The instance does not explicitly encrypt its root EBS volume, so data at rest may be unencrypted when account-level EBS encryption is not enabled."
    },
    {
      "check_id": "CKV_AWS_79",
      "title": "EC2 instance does not require IMDSv2",
      "resource": "aws_instance.web",
      "severity": "HIGH",
      "explanation": "No metadata options are configured, allowing use of IMDSv1 and increasing the risk of credential theft through server-side request forgery."
    },
    {
      "check_id": "CKV_AWS_126",
      "title": "EC2 detailed monitoring is disabled",
      "resource": "aws_instance.web",
      "severity": "LOW",
      "explanation": "Detailed CloudWatch monitoring is not enabled, reducing the granularity of telemetry available for operational and security incident detection."
    }
  ],
  "patched_code": "resource \"aws_instance\" \"web\" {\n  ami                    = \"${var.ami}\"\n  instance_type          = \"t2.micro\"\n  subnet_id              = \"${aws_subnet.public-subnet.id}\"\n  vpc_security_group_ids = [\"${aws_security_group.sgweb.id}\"]\n  monitoring             = true\n\n  root_block_device {\n    encrypted = true\n  }\n\n  metadata_options {\n    http_endpoint               = \"enabled\"\n    http_tokens                 = \"required\"\n    http_put_response_hop_limit = 1\n  }\n}\n",
  "fix_summary": "Enforced encryption for the instance root volume, required IMDSv2 with a restricted metadata hop limit, and enabled detailed CloudWatch monitoring."
}
